import java.util.*;

public class Main {
    long subArrayRanges(int[] nums) {
        int n = nums.length;
        long total = 0;
        for (int i = 0; i < n; i++) {
            int mn = nums[i], mx = nums[i];
            for (int j = i; j < n; j++) {                                            // extend the subarray one element at a time
                mn = Math.min(mn, nums[j]);
                mx = Math.max(mx, nums[j]);
                total += mx - mn;                                                        // this subarray's range, added directly
            }
        }
        return total;
    }

    public static void main(String[] args) {
        Main solution = new Main();
        int[] nums = {1, 3, 3};
        System.out.println(solution.subArrayRanges(nums));
    }
}

