import java.util.*;

public class Main {
    long contributionSum(int[] nums, boolean wantMax) {
        int n = nums.length;
        int[] prevBoundary = new int[n];
        int[] nextBoundary = new int[n];
        Deque<Integer> stack = new ArrayDeque<>();
        for (int i = 0; i < n; i++) {
            while (!stack.isEmpty() && !better(nums[stack.peek()], nums[i], wantMax)) {         // pop everything NOT strictly better than nums[i]
                stack.pop();
            }
            prevBoundary[i] = stack.isEmpty() ? -1 : stack.peek();
            stack.push(i);
        }
        stack.clear();
        for (int i = n - 1; i >= 0; i--) {
            while (!stack.isEmpty() && better(nums[i], nums[stack.peek()], wantMax)) {          // pop everything STRICTLY worse than nums[i] (ties stay, giving <=)
                stack.pop();
            }
            nextBoundary[i] = stack.isEmpty() ? n : stack.peek();
            stack.push(i);
        }
        long total = 0;
        for (int i = 0; i < n; i++) {
            long left = i - prevBoundary[i];                                                       // choices for the subarray's LEFT edge
            long right = nextBoundary[i] - i;                                                       // choices for the subarray's RIGHT edge
            total += (long) nums[i] * left * right;                                                 // nums[i] is the extreme in exactly left*right subarrays
        }
        return total;
    }

    boolean better(int a, int b, boolean wantMax) {                                                    // "better" = bigger for max, smaller for min
        return wantMax ? a > b : a < b;
    }

    long subArrayRanges(int[] nums) {
        return contributionSum(nums, true) - contributionSum(nums, false);                             // sum(max) - sum(min) over ALL subarrays
    }

    public static void main(String[] args) {
        Main solution = new Main();
        int[] nums = {1, 3, 3};
        System.out.println(solution.subArrayRanges(nums));
    }
}

